import{setSoundEnabled}from'./audio.js';export function setupDesktopControls(input){const keys=new Set();window.addEventListener('keydown',e=>{keys.add(e.code);if(e.code==='Space')input.jumpRequested=true;if(e.code==='KeyE')input.interactRequested=true});window.addEventListener('keyup',e=>keys.delete(e.code));input.updateFromKeyboard=()=>{input.moveInput.set((keys.has('KeyD')?1:0)-(keys.has('KeyA')?1:0),(keys.has('KeyW')?1:0)-(keys.has('KeyS')?1:0))}}export function setupMouseCamera(canvas,cameraState){let dragging=false,lastX=0;canvas.addEventListener('pointerdown',e=>{if(e.pointerType==='touch')return;dragging=true;lastX=e.clientX});window.addEventListener('pointerup',()=>dragging=false);window.addEventListener('pointermove',e=>{if(!dragging)return;cameraState.yaw-=(e.clientX-lastX)*.004;lastX=e.clientX})}export function setupTouchControls(input,cameraState){const zone=document.getElementById('joystick-zone'),knob=document.getElementById('joystick-knob'),canvas=document.getElementById('game-canvas');let joystickId=null,cameraId=null,cameraLastX=0,center={x:0,y:0};zone.addEventListener('pointerdown',e=>{joystickId=e.pointerId;const r=zone.getBoundingClientRect();center={x:r.left+r.width/2,y:r.top+r.height/2};zone.setPointerCapture(e.pointerId)});zone.addEventListener('pointermove',e=>{if(e.pointerId!==joystickId)return;const r=zone.getBoundingClientRect(),max=r.width/2;let dx=e.clientX-center.x,dy=e.clientY-center.y;const d=Math.hypot(dx,dy);if(d>max){dx=dx/d*max;dy=dy/d*max}knob.style.transform=`translate(${dx}px,${dy}px)`;input.moveInput.set(dx/max,-dy/max)});const release=e=>{if(e.pointerId!==joystickId)return;joystickId=null;knob.style.transform='';input.moveInput.set(0,0)};zone.addEventListener('pointerup',release);zone.addEventListener('pointercancel',release);canvas.addEventListener('pointerdown',e=>{if(e.pointerType!=='touch'||cameraId!==null)return;cameraId=e.pointerId;cameraLastX=e.clientX});canvas.addEventListener('pointermove',e=>{if(e.pointerId!==cameraId)return;cameraState.yaw-=(e.clientX-cameraLastX)*.005;cameraLastX=e.clientX});canvas.addEventListener('pointerup',e=>{if(e.pointerId===cameraId)cameraId=null});document.getElementById('jump-button').addEventListener('pointerdown',()=>input.jumpRequested=true);document.getElementById('interact-button').addEventListener('pointerdown',()=>input.interactRequested=true)}export function setupPanels(){document.getElementById('inventory-button').addEventListener('click',()=>document.getElementById('inventory-panel').classList.toggle('hidden'));document.getElementById('settings-button').addEventListener('click',()=>document.getElementById('settings-panel').classList.toggle('hidden'));document.querySelectorAll('[data-close]').forEach(b=>b.addEventListener('click',()=>document.getElementById(b.dataset.close).classList.add('hidden')));document.getElementById('sound-toggle').addEventListener('change',e=>setSoundEnabled(e.target.checked))}